//! Ciphertext blob storage (§4.2).
//!
//! Blobs are the serialized [`faro_proto::EncryptedItem`]s of event bodies and
//! reports: ciphertext plus per-recipient wrapped keys. The server cannot read
//! them. They are kept out of the database so the DB stays small (a Pi's SD
//! card, a cheap VPS) and so large instances can move them to S3.
//!
//! Blob ids are random 128-bit lowercase hex strings generated by the server.
//! [`BlobId::parse`] accepts nothing else, which makes path traversal through a
//! blob id structurally impossible for the local-disk store.
//!
//! Not implemented: an S3-compatible store (MinIO, R2, B2, AWS) behind the
//! same trait, with presigned GET URLs for ally downloads. No S3 SDK is pulled
//! in yet; see the stage report.

use std::future::Future;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::pin::Pin;

/// A validated blob identifier: exactly 32 lowercase hex characters.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct BlobId(String);

impl BlobId {
    pub fn new_random() -> Self {
        BlobId(crate::tokens::new_hex_id())
    }

    pub fn parse(s: &str) -> Option<Self> {
        let ok = s.len() == 32 && s.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'));
        ok.then(|| BlobId(s.to_owned()))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for BlobId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

#[derive(Debug, thiserror::Error)]
pub enum BlobError {
    #[error("blob not found")]
    NotFound,
    #[error("blob already exists")]
    AlreadyExists,
    #[error("blob I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("blob task failed: {0}")]
    Join(String),
}

pub type BlobFuture<'a, T> = Pin<Box<dyn Future<Output = Result<T, BlobError>> + Send + 'a>>;

/// Storage for opaque ciphertext blobs.
///
/// Implementations must make `put` atomic (a reader never sees a partial
/// blob) and durable once it returns, and `delete` idempotent.
pub trait BlobStore: Send + Sync + std::fmt::Debug + 'static {
    fn put<'a>(&'a self, id: &'a BlobId, data: Vec<u8>) -> BlobFuture<'a, ()>;
    fn get<'a>(&'a self, id: &'a BlobId) -> BlobFuture<'a, Vec<u8>>;
    fn delete<'a>(&'a self, id: &'a BlobId) -> BlobFuture<'a, ()>;
    /// Blobs last written before `cutoff_ms` (Unix ms), for the retention
    /// worker's orphan sweep. Also removes abandoned temporary files older
    /// than the cutoff.
    fn list_older_than(&self, cutoff_ms: i64) -> BlobFuture<'_, Vec<BlobId>>;
}

/// Blobs as files under `<root>/aa/bb/<id>` (fan-out keeps directories small).
#[derive(Debug, Clone)]
pub struct LocalDiskBlobStore {
    root: PathBuf,
}

impl LocalDiskBlobStore {
    /// Use (and create) `root`. Typically `<data_dir>/blobs`.
    pub fn open(root: impl Into<PathBuf>) -> std::io::Result<Self> {
        let root = root.into();
        std::fs::create_dir_all(root.join("tmp"))?;
        Ok(LocalDiskBlobStore { root })
    }

    fn path_for(&self, id: &BlobId) -> PathBuf {
        let s = id.as_str();
        self.root.join(&s[0..2]).join(&s[2..4]).join(s)
    }
}

async fn blocking<T: Send + 'static>(
    f: impl FnOnce() -> Result<T, BlobError> + Send + 'static,
) -> Result<T, BlobError> {
    tokio::task::spawn_blocking(f)
        .await
        .map_err(|e| BlobError::Join(e.to_string()))?
}

fn sync_dir(dir: &Path) {
    // Directory fsync makes the rename durable on Linux; it is a no-op or
    // unsupported on some platforms, so failures are ignored.
    if let Ok(d) = std::fs::File::open(dir) {
        let _ = d.sync_all();
    }
}

impl BlobStore for LocalDiskBlobStore {
    fn put<'a>(&'a self, id: &'a BlobId, data: Vec<u8>) -> BlobFuture<'a, ()> {
        let final_path = self.path_for(id);
        let tmp =
            self.root
                .join("tmp")
                .join(format!("{}.{}", id.as_str(), crate::tokens::new_hex_id()));
        Box::pin(blocking(move || {
            if final_path.exists() {
                return Err(BlobError::AlreadyExists);
            }
            let parent = final_path
                .parent()
                .ok_or_else(|| BlobError::Io(std::io::Error::other("blob path has no parent")))?;
            std::fs::create_dir_all(parent)?;
            let write = || -> std::io::Result<()> {
                let mut opts = std::fs::OpenOptions::new();
                opts.write(true).create_new(true);
                #[cfg(unix)]
                {
                    use std::os::unix::fs::OpenOptionsExt;
                    opts.mode(0o600);
                }
                let mut f = opts.open(&tmp)?;
                f.write_all(&data)?;
                f.sync_all()?;
                std::fs::rename(&tmp, &final_path)?;
                Ok(())
            };
            if let Err(e) = write() {
                let _ = std::fs::remove_file(&tmp);
                return Err(e.into());
            }
            sync_dir(parent);
            Ok(())
        }))
    }

    fn get<'a>(&'a self, id: &'a BlobId) -> BlobFuture<'a, Vec<u8>> {
        let path = self.path_for(id);
        Box::pin(blocking(move || match std::fs::read(&path) {
            Ok(v) => Ok(v),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(BlobError::NotFound),
            Err(e) => Err(e.into()),
        }))
    }

    fn delete<'a>(&'a self, id: &'a BlobId) -> BlobFuture<'a, ()> {
        let path = self.path_for(id);
        Box::pin(blocking(move || match std::fs::remove_file(&path) {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(e.into()),
        }))
    }

    fn list_older_than(&self, cutoff_ms: i64) -> BlobFuture<'_, Vec<BlobId>> {
        let root = self.root.clone();
        Box::pin(blocking(move || {
            let older = |p: &Path| -> bool {
                std::fs::metadata(p)
                    .and_then(|m| m.modified())
                    .ok()
                    .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                    .and_then(|d| i64::try_from(d.as_millis()).ok())
                    .is_some_and(|ms| ms < cutoff_ms)
            };
            let mut out = Vec::new();
            for l1 in read_dir_names(&root)? {
                if l1 == "tmp" {
                    for t in read_dir_names(&root.join("tmp"))? {
                        let p = root.join("tmp").join(&t);
                        if older(&p) {
                            let _ = std::fs::remove_file(&p);
                        }
                    }
                    continue;
                }
                if l1.len() != 2 {
                    continue;
                }
                for l2 in read_dir_names(&root.join(&l1))? {
                    for name in read_dir_names(&root.join(&l1).join(&l2))? {
                        // Only files at their canonical path count; anything
                        // else in the tree is left alone.
                        let Some(id) = BlobId::parse(&name) else {
                            continue;
                        };
                        if name[0..2] != l1 || name[2..4] != l2 {
                            continue;
                        }
                        if older(&root.join(&l1).join(&l2).join(&name)) {
                            out.push(id);
                        }
                    }
                }
            }
            Ok(out)
        }))
    }
}

/// Entry names of a directory (empty if it does not exist).
fn read_dir_names(dir: &Path) -> Result<Vec<String>, BlobError> {
    let rd = match std::fs::read_dir(dir) {
        Ok(rd) => rd,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(e) => return Err(e.into()),
    };
    let mut v = Vec::new();
    for entry in rd {
        if let Some(n) = entry?.file_name().to_str() {
            v.push(n.to_owned());
        }
    }
    Ok(v)
}

impl LocalDiskBlobStore {
    /// The root directory (for backups).
    pub fn root(&self) -> &Path {
        &self.root
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn blob_ids_reject_traversal_and_junk() {
        assert!(BlobId::parse(&"a".repeat(32)).is_some());
        for bad in [
            "",
            "../../../../etc/passwd",
            &"A".repeat(32),
            &"a".repeat(31),
            &"a".repeat(33),
            "0123456789abcdef0123456789abcde/",
            "0123456789abcdef0123456789abcd..",
        ] {
            assert!(BlobId::parse(bad).is_none(), "{bad:?}");
        }
        assert!(BlobId::parse(BlobId::new_random().as_str()).is_some());
    }

    #[tokio::test]
    async fn put_get_delete() {
        let dir = tempfile::tempdir().unwrap();
        let store = LocalDiskBlobStore::open(dir.path().join("blobs")).unwrap();
        let id = BlobId::new_random();
        store.put(&id, b"ciphertext".to_vec()).await.unwrap();
        assert_eq!(store.get(&id).await.unwrap(), b"ciphertext");
        let s = id.as_str();
        assert!(dir
            .path()
            .join("blobs")
            .join(&s[..2])
            .join(&s[2..4])
            .join(s)
            .is_file());
        assert!(matches!(
            store.put(&id, b"other".to_vec()).await,
            Err(BlobError::AlreadyExists)
        ));
        store.delete(&id).await.unwrap();
        store.delete(&id).await.unwrap(); // idempotent
        assert!(matches!(store.get(&id).await, Err(BlobError::NotFound)));
        // Nothing was written before the epoch.
        assert!(store.list_older_than(0).await.unwrap().is_empty());
        // The temp dir is empty after successful writes.
        assert_eq!(
            std::fs::read_dir(dir.path().join("blobs/tmp"))
                .unwrap()
                .count(),
            0
        );
    }
}

#[cfg(test)]
mod list_tests {
    use super::*;

    #[tokio::test]
    async fn lists_only_canonical_old_blobs_and_cleans_tmp() {
        let dir = tempfile::tempdir().unwrap();
        let store = LocalDiskBlobStore::open(dir.path().join("b")).unwrap();
        let id = BlobId::new_random();
        store.put(&id, b"x".to_vec()).await.unwrap();
        // A stray file in the tree, and an abandoned temp file.
        std::fs::write(dir.path().join("b/README"), b"hi").unwrap();
        std::fs::write(dir.path().join("b/tmp/abandoned"), b"x").unwrap();
        let far_future = i64::MAX;
        let listed = store.list_older_than(far_future).await.unwrap();
        assert_eq!(listed, vec![id.clone()]);
        assert!(!dir.path().join("b/tmp/abandoned").exists());
        assert!(dir.path().join("b/README").exists());
        assert!(store.list_older_than(0).await.unwrap().is_empty());
    }
}
